    // Crash reports: the one-time ask (CrashReports)
    "CRASH REPORTS?" to Tr(ja = "クラッシュ レポート？", fr = "RAPPORTS DE PLANTAGE ?", de = "ABSTURZBERICHTE?", it = "SEGNALAZIONI CRASH?", es = "¿INFORMES DE FALLOS?", br = "RELATÓRIOS DE FALHAS?", pt = "RELATÓRIOS DE FALHAS?"),
    "When PokéDaisy crashes, it can send a report so the bug gets fixed sooner: the device model, Android version and where the app crashed. Never your ROMs, saves or anything personal. You can change this any time in Settings." to Tr(ja = "PokéDaisyが とまったとき、レポートを おくれます。バグが はやく なおります：きしゅ、Androidの バージョン、とまった ばしょ。ROMや セーブ、こじんの じょうほうは おくりません。せっていで いつでも かえられます。", fr = "Quand PokéDaisy plante, il peut envoyer un rapport pour que le bug soit corrigé plus vite : le modèle de l'appareil, la version d'Android et l'endroit du plantage. Jamais vos ROM, vos sauvegardes ni rien de personnel. Modifiable à tout moment dans les Options.", de = "Wenn PokéDaisy abstürzt, kann es einen Bericht senden, damit der Fehler schneller behoben wird: Gerätemodell, Android-Version und die Absturzstelle. Nie deine ROMs, Spielstände oder Persönliches. Jederzeit in den Optionen änderbar.", it = "Quando PokéDaisy si blocca, può inviare una segnalazione per correggere prima il bug: modello del dispositivo, versione di Android e punto del crash. Mai le tue ROM, i salvataggi o dati personali. Puoi cambiarlo quando vuoi nelle Opzioni.", es = "Cuando PokéDaisy falla, puede enviar un informe para que el error se corrija antes: el modelo del dispositivo, la versión de Android y dónde falló. Nunca tus ROM, partidas ni nada personal. Puedes cambiarlo cuando quieras en Ajustes.", br = "Quando o PokéDaisy trava, ele pode enviar um relatório para o bug ser corrigido mais rápido: o modelo do aparelho, a versão do Android e onde o app travou. Nunca suas ROMs, saves ou nada pessoal. Você pode mudar isso a qualquer momento nas Configurações.", pt = "Quando o PokéDaisy falha, pode enviar um relatório para o erro ser corrigido mais depressa: o modelo do dispositivo, a versão do Android e onde a app falhou. Nunca as suas ROMs, gravações nem nada pessoal. Pode mudar isto a qualquer momento nas Definições."),
    "SEND REPORTS" to Tr(ja = "おくる", fr = "ENVOYER", de = "SENDEN", it = "INVIA", es = "ENVIAR", br = "ENVIAR", pt = "ENVIAR"),

    // App update
    "PokéDaisy {0} is the newest version" to Tr(ja = "PokéDaisy {0}は さいしんばんです", fr = "PokéDaisy {0} est la dernière version", de = "PokéDaisy {0} ist die neueste Version", it = "PokéDaisy {0} è la versione più recente", es = "PokéDaisy {0} es la versión más reciente", br = "PokéDaisy {0} é a versão mais recente", pt = "PokéDaisy {0} é a versão mais recente"),
    "THE DOWNLOAD ISN'T A POKéDAISY UPDATE - NOT INSTALLED" to Tr(ja = "PokéDaisyの アップデートでは ありません - インストールしません", fr = "CE N'EST PAS UNE MISE À JOUR DE POKéDAISY - NON INSTALLÉE", de = "KEIN POKéDAISY-UPDATE - NICHT INSTALLIERT", it = "NON È UN AGGIORNAMENTO DI POKéDAISY - NON INSTALLATO", es = "NO ES UNA ACTUALIZACIÓN DE POKéDAISY - NO SE INSTALA", br = "NÃO É UMA ATUALIZAÇÃO DO POKéDAISY - NÃO INSTALADA", pt = "NÃO É UMA ATUALIZAÇÃO DO POKéDAISY - NÃO INSTALADA"),
    "THE DOWNLOAD FAILED - CHECK THE CONNECTION AND TRY AGAIN" to Tr(ja = "ダウンロードに しっぱいしました - せつぞくを たしかめて もういちど", fr = "ÉCHEC DU TÉLÉCHARGEMENT - VÉRIFIEZ LA CONNEXION ET RÉESSAYEZ", de = "DOWNLOAD FEHLGESCHLAGEN - VERBINDUNG PRÜFEN UND NOCHMAL VERSUCHEN", it = "DOWNLOAD NON RIUSCITO - CONTROLLA LA CONNESSIONE E RIPROVA", es = "LA DESCARGA FALLÓ - REVISA LA CONEXIÓN E INTÉNTALO DE NUEVO", br = "FALHA NO DOWNLOAD - VERIFIQUE A CONEXÃO E TENTE DE NOVO", pt = "A TRANSFERÊNCIA FALHOU - VERIFIQUE A LIGAÇÃO E TENTE DE NOVO"),
    "Allow PokéDaisy to install apps, then come back" to Tr(ja = "PokéDaisyに アプリの インストールを きょかして もどってください", fr = "Autorisez PokéDaisy à installer des applis, puis revenez", de = "Erlaube PokéDaisy, Apps zu installieren, und komm zurück", it = "Consenti a PokéDaisy di installare app, poi torna qui", es = "Permite que PokéDaisy instale apps y vuelve", br = "Permita que o PokéDaisy instale apps e volte", pt = "Permita que o PokéDaisy instale aplicações e volte"),
    "ANDROID'S INSTALLER DIDN'T OPEN - GET THE APK FROM THE RELEASE PAGE" to Tr(ja = "Androidの インストーラーが ひらきません - リリースページから APKを いれてください", fr = "L'INSTALLATEUR D'ANDROID NE S'EST PAS OUVERT - PRENEZ L'APK SUR LA PAGE DE VERSION", de = "ANDROIDS INSTALLER GING NICHT AUF - HOL DIE APK VON DER RELEASE-SEITE", it = "IL PROGRAMMA DI INSTALLAZIONE NON SI È APERTO - SCARICA L'APK DALLA PAGINA DELLA VERSIONE", es = "EL INSTALADOR DE ANDROID NO SE ABRIÓ - DESCARGA EL APK DE LA PÁGINA DE LA VERSIÓN", br = "O INSTALADOR DO ANDROID NÃO ABRIU - BAIXE O APK NA PÁGINA DA VERSÃO", pt = "O INSTALADOR DO ANDROID NÃO ABRIU - TRANSFIRA O APK NA PÁGINA DA VERSÃO"),
    "UPDATE AVAILABLE" to Tr(ja = "アップデートが あります", fr = "MISE À JOUR DISPO", de = "UPDATE VERFÜGBAR", it = "AGGIORNAMENTO", es = "ACTUALIZACIÓN", br = "ATUALIZAÇÃO", pt = "ATUALIZAÇÃO"),
    "PokéDaisy {0} is out - you have {1}." to Tr(ja = "PokéDaisy {0}が でました - いまは {1}です。", fr = "PokéDaisy {0} est sorti - vous avez la {1}.", de = "PokéDaisy {0} ist da - du hast {1}.", it = "È uscito PokéDaisy {0} - hai la {1}.", es = "Ya salió PokéDaisy {0} - tienes la {1}.", br = "Saiu o PokéDaisy {0} - você tem a {1}.", pt = "Saiu o PokéDaisy {0} - tem a {1}."),
