    "Undid save (slot {0})" to Tr(ja = "ほぞんを とりけしました (スロット {0})", fr = "Enregistrement annulé ({0})", de = "Speichern rückgängig (Slot {0})", it = "Salvataggio annullato (slot {0})", es = "Guardado deshecho (ranura {0})", br = "Salvamento desfeito (espaço {0})", pt = "Gravação desfeita (espaço {0})"),
