    "YOUR ROMS FOLDERS" to Tr(ja = "ROMフォルダ", fr = "VOS DOSSIERS DE ROM", de = "DEINE ROM-ORDNER", it = "LE TUE CARTELLE ROM", es = "TUS CARPETAS DE ROM", br = "SUAS PASTAS DE ROMS", pt = "AS SUAS PASTAS DE ROMS"),
    "Pick the folders you keep your games in. PokéDaisy adds every game from them that the second screen supports, plays them right where they are (nothing is copied), and looks for new ones each time you open the app." to Tr(ja = "ゲームを いれている フォルダを えらんでください。 PokéDaisyは サブがめんが たいおうする ゲームを すべて ついかし、 その ばしょの まま プレイして (コピーは しません)、 アプリを ひらく たびに あたらしい ゲームを さがします。", fr = "Choisissez les dossiers où vous rangez vos jeux. PokéDaisy ajoute chaque jeu pris en charge par le 2nd écran, le lance sur place (rien n'est copié) et cherche les nouveaux à chaque ouverture de l'appli.", de = "Wähle die Ordner mit deinen Spielen. PokéDaisy fügt jedes Spiel daraus hinzu, das der 2. Bildschirm unterstützt, spielt es direkt dort (nichts wird kopiert) und sucht bei jedem App-Start nach neuen.", it = "Scegli le cartelle dove tieni i tuoi giochi. PokéDaisy aggiunge ogni gioco supportato dal secondo schermo, lo avvia lì dov'è (nulla viene copiato) e cerca quelli nuovi ogni volta che apri l'app.", es = "Elige las carpetas donde guardas tus juegos. PokéDaisy añade cada juego compatible con la 2.ª pantalla, lo abre donde está (no se copia nada) y busca nuevos cada vez que abres la app.", br = "Escolha as pastas onde você guarda seus jogos. O PokéDaisy adiciona todos os jogos delas que a segunda tela suporta, roda cada um onde está (nada é copiado) e procura novos sempre que você abre o app.", pt = "Escolha as pastas onde guarda os seus jogos. O PokéDaisy adiciona todos os jogos delas que o segundo ecrã suporta, abre-os onde estão (nada é copiado) e procura novos sempre que abre a app."),
    "This is optional: skip it and add games one at a time with + in the library. You can add folders later with + or in SETTINGS > FOLDERS." to Tr(ja = "これは しなくても だいじょうぶ: スキップして ライブラリの + で ひとつずつ ついか できます。 フォルダは あとで + か せってい > フォルダ でも ついか できます。", fr = "C'est facultatif : passez et ajoutez les jeux un par un avec + dans la bibliothèque. Vous pourrez ajouter des dossiers plus tard avec + ou dans OPTIONS > DOSSIERS.", de = "Das ist optional: Überspring es und füge Spiele einzeln mit + in der Bibliothek hinzu. Ordner kannst du später mit + oder unter OPTIONEN > ORDNER hinzufügen.", it = "È facoltativo: saltalo e aggiungi i giochi uno alla volta con + nella libreria. Puoi aggiungere cartelle più tardi con + o in OPZIONI > CARTELLE.", es = "Es opcional: omítelo y añade juegos de uno en uno con + en la biblioteca. Puedes añadir carpetas más tarde con + o en AJUSTES > CARPETAS.", br = "É opcional: pule e adicione jogos um a um com + na biblioteca. Você pode adicionar pastas depois com + ou em CONFIGURAÇÕES > PASTAS.", pt = "É opcional: salte este passo e adicione jogos um a um com + na biblioteca. Pode adicionar pastas mais tarde com + ou em DEFINIÇÕES > PASTAS."),
    "Android asks you to allow All files access first, so PokéDaisy can open games and saves outside its own folder. Turn it on and come back here." to Tr(ja = "さきに Androidが 「すべての ファイルへの アクセス」の きょかを もとめます。 PokéDaisyが じぶんの フォルダの そとの ゲームや セーブを ひらく ためです。 オンにして ここへ もどってください。", fr = "Android vous demande d'abord d'autoriser l'accès à tous les fichiers, pour que PokéDaisy puisse ouvrir jeux et sauvegardes hors de son dossier. Activez-le et revenez ici.", de = "Android fragt zuerst nach dem Zugriff auf alle Dateien, damit PokéDaisy Spiele und Speicherstände außerhalb seines Ordners öffnen kann. Schalte ihn ein und komm hierher zurück.", it = "Android chiede prima di consentire l'accesso a tutti i file, così PokéDaisy può aprire giochi e salvataggi fuori dalla sua cartella. Attivalo e torna qui.", es = "Android te pide primero permitir el acceso a todos los archivos, para que PokéDaisy pueda abrir juegos y partidas fuera de su carpeta. Actívalo y vuelve aquí.", br = "O Android pede primeiro que você permita o acesso a todos os arquivos, para que o PokéDaisy possa abrir jogos e saves fora da própria pasta. Ative e volte aqui.", pt = "O Android pede primeiro que permita o acesso a todos os ficheiros, para que o PokéDaisy possa abrir jogos e gravações fora da sua pasta. Ative-o e volte aqui."),
    "LOOKING FOR GAMES… {0} / {1}" to Tr(ja = "ゲームを さがしちゅう… {0} / {1}", fr = "RECHERCHE DE JEUX… {0} / {1}", de = "SUCHE SPIELE… {0} / {1}", it = "CERCO GIOCHI… {0} / {1}", es = "BUSCANDO JUEGOS… {0} / {1}", br = "PROCURANDO JOGOS… {0} / {1}", pt = "A PROCURAR JOGOS… {0} / {1}"),
    "No supported games in there. Add another folder, or skip and add games with + later." to Tr(ja = "たいおうする ゲームが ありません。 べつの フォルダを ついかするか、 スキップして あとで + で ついかしてください。", fr = "Aucun jeu pris en charge ici. Ajoutez un autre dossier, ou passez et ajoutez des jeux avec + plus tard.", de = "Keine unterstützten Spiele darin. Füge einen anderen Ordner hinzu oder überspring es und füge später Spiele mit + hinzu.", it = "Nessun gioco supportato qui. Aggiungi un'altra cartella, o salta e aggiungi i giochi con + più tardi.", es = "No hay juegos compatibles ahí. Añade otra carpeta, u omite y añade juegos con + más tarde.", br = "Nenhum jogo compatível aí. Adicione outra pasta ou pule e adicione jogos com + depois.", pt = "Nenhum jogo compatível aí. Adicione outra pasta ou salte e adicione jogos com + mais tarde."),
    "FOUND 1 GAME" to Tr(ja = "ゲームを 1こ みつけた", fr = "1 JEU TROUVÉ", de = "1 SPIEL GEFUNDEN", it = "1 GIOCO TROVATO", es = "1 JUEGO ENCONTRADO", br = "1 JOGO ENCONTRADO", pt = "1 JOGO ENCONTRADO"),
    "FOUND {0} GAMES" to Tr(ja = "ゲームを {0}こ みつけた", fr = "{0} JEUX TROUVÉS", de = "{0} SPIELE GEFUNDEN", it = "{0} GIOCHI TROVATI", es = "{0} JUEGOS ENCONTRADOS", br = "{0} JOGOS ENCONTRADOS", pt = "{0} JOGOS ENCONTRADOS"),
    "GAME SAVES" to Tr(ja = "セーブデータ", fr = "SAUVEGARDES", de = "SPEICHERSTÄNDE", it = "SALVATAGGI", es = "PARTIDAS GUARDADAS", br = "SAVES DOS JOGOS", pt = "JOGOS GUARDADOS"),
    "Where should your saves go? If you already play these games in another emulator, pick its save folder (RetroArch's, for one) and carry on with the same saves: a game finds its save by the ROM's file name (.sav or .srm)." to Tr(ja = "セーブを どこに おきますか? ほかの エミュレーターで あそんでいるなら、 その セーブフォルダ (たとえば RetroArchの)を えらべば おなじ セーブで つづけられます: ゲームは ROMの ファイルめい (.sav か .srm)で セーブを さがします。", fr = "Où mettre vos sauvegardes ? Si vous jouez déjà à ces jeux dans un autre émulateur, choisissez son dossier de sauvegardes (celui de RetroArch, par exemple) et continuez avec les mêmes : un jeu trouve sa sauvegarde par le nom de fichier de la ROM (.sav ou .srm).", de = "Wohin mit deinen Speicherständen? Spielst du diese Spiele schon in einem anderen Emulator, wähle seinen Speicherordner (z. B. den von RetroArch) und spiel mit denselben weiter: Ein Spiel findet seinen Speicherstand über den Dateinamen des ROMs (.sav oder .srm).", it = "Dove vanno i salvataggi? Se giochi già a questi giochi in un altro emulatore, scegli la sua cartella dei salvataggi (quella di RetroArch, per esempio) e continua con gli stessi: un gioco trova il suo salvataggio dal nome file della ROM (.sav o .srm).", es = "¿Dónde van tus partidas? Si ya juegas a estos juegos en otro emulador, elige su carpeta de partidas (la de RetroArch, por ejemplo) y sigue con las mismas: cada juego encuentra su partida por el nombre de archivo de la ROM (.sav o .srm).", br = "Onde ficam seus saves? Se você já joga esses jogos em outro emulador, escolha a pasta de saves dele (a do RetroArch, por exemplo) e continue com os mesmos saves: cada jogo acha o save pelo nome do arquivo da ROM (.sav ou .srm).", pt = "Onde ficam os jogos guardados? Se já joga estes jogos noutro emulador, escolha a pasta de gravações dele (a do RetroArch, por exemplo) e continue com as mesmas gravações: cada jogo encontra a sua gravação pelo nome do ficheiro da ROM (.sav ou .srm)."),
    "KEEP THEM IN POKéDAISY" to Tr(ja = "POKéDAISYに おく", fr = "LES GARDER DANS POKéDAISY", de = "IN POKéDAISY BEHALTEN", it = "TIENILI IN POKéDAISY", es = "GUARDAR EN POKéDAISY", br = "MANTER NO POKéDAISY", pt = "GUARDAR NO POKéDAISY"),
    "DEFAULT" to Tr(ja = "ひょうじゅん", fr = "PAR DÉFAUT", de = "STANDARD", it = "PREDEFINITO", es = "POR DEFECTO", br = "PADRÃO", pt = "PREDEFINIDO"),
    "1 SAVE" to Tr(ja = "セーブ 1こ", fr = "1 SAUVEGARDE", de = "1 SPEICHERSTAND", it = "1 SALVATAGGIO", es = "1 PARTIDA", br = "1 SAVE", pt = "1 GRAVAÇÃO"),
    "{0} SAVES" to Tr(ja = "セーブ {0}こ", fr = "{0} SAUVEGARDES", de = "{0} SPEICHERSTÄNDE", it = "{0} SALVATAGGI", es = "{0} PARTIDAS", br = "{0} SAVES", pt = "{0} GRAVAÇÕES"),
    "CHOOSE ANOTHER FOLDER…" to Tr(ja = "べつの フォルダを えらぶ…", fr = "CHOISIR UN AUTRE DOSSIER…", de = "ANDEREN ORDNER WÄHLEN…", it = "SCEGLI UN'ALTRA CARTELLA…", es = "ELEGIR OTRA CARPETA…", br = "ESCOLHER OUTRA PASTA…", pt = "ESCOLHER OUTRA PASTA…"),
    "Choosing a folder asks for All files access first, as games and saves are opened by path." to Tr(ja = "フォルダを えらぶ まえに 「すべての ファイルへの アクセス」を もとめます。 ゲームと セーブは パスで ひらく ためです。", fr = "Choisir un dossier demande d'abord l'accès à tous les fichiers, car jeux et sauvegardes sont ouverts par leur chemin.", de = "Die Ordnerwahl fragt zuerst nach dem Zugriff auf alle Dateien, da Spiele und Speicherstände über ihren Pfad geöffnet werden.", it = "Scegliere una cartella richiede prima l'accesso a tutti i file, perché giochi e salvataggi si aprono dal percorso.", es = "Elegir una carpeta pide primero el acceso a todos los archivos, ya que juegos y partidas se abren por su ruta.", br = "Escolher uma pasta pede primeiro o acesso a todos os arquivos, pois jogos e saves são abertos pelo caminho.", pt = "Escolher uma pasta pede primeiro o acesso a todos os ficheiros, pois jogos e gravações são abertos pelo caminho."),
    "You can change this later in SETTINGS > FOLDERS." to Tr(ja = "あとで せってい > フォルダ で かえられます。", fr = "Vous pourrez le changer plus tard dans OPTIONS > DOSSIERS.", de = "Das kannst du später unter OPTIONEN > ORDNER ändern.", it = "Puoi cambiarlo più tardi in OPZIONI > CARTELLE.", es = "Puedes cambiarlo más tarde en AJUSTES > CARPETAS.", br = "Você pode mudar isso depois em CONFIGURAÇÕES > PASTAS.", pt = "Pode mudar isto mais tarde em DEFINIÇÕES > PASTAS."),
    "COVER ART (OPTIONAL)" to Tr(ja = "カバー (にんい)", fr = "JAQUETTES (FACULTATIF)", de = "COVER (OPTIONAL)", it = "COPERTINE (FACOLTATIVO)", es = "PORTADAS (OPCIONAL)", br = "CAPAS (OPCIONAL)", pt = "CAPAS (OPCIONAL)"),
    "Library covers are box art from RetroAchievements, or icons from SteamGridDB for games it doesn't have. Each needs your own free key: open the site, copy the key and paste it below - one is enough." to Tr(ja = "ライブラリの カバーは RetroAchievementsの パッケージ、 なければ SteamGridDBの アイコンです。 どちらも じぶんの むりょうの キーが ひつようです: サイトを ひらいて キーを コピーし したに はりつけて ください — ひとつで じゅうぶんです。", fr = "Les jaquettes sont les boîtes de RetroAchievements, ou des icônes de SteamGridDB pour les jeux qu'il n'a pas. Chacun demande votre propre clé gratuite : ouvrez le site, copiez la clé et collez-la ci-dessous - une seule suffit.", de = "Bibliothek-Cover sind Verpackungen von RetroAchievements oder Icons von SteamGridDB für Spiele, die es nicht hat. Beide brauchen deinen eigenen kostenlosen Schlüssel: Öffne die Seite, kopiere den Schlüssel und füge ihn unten ein - einer reicht.", it = "Le copertine sono le confezioni di RetroAchievements, o icone di SteamGridDB per i giochi che non ha. Ognuno richiede la tua chiave gratuita: apri il sito, copia la chiave e incollala qui sotto - ne basta una.", es = "Las portadas son cajas de RetroAchievements, o iconos de SteamGridDB para los juegos que no tiene. Cada uno necesita tu propia clave gratis: abre el sitio, copia la clave y pégala abajo - con una basta.", br = "As capas da biblioteca são caixas do RetroAchievements, ou ícones do SteamGridDB para os jogos que ele não tem. Cada um precisa da sua própria chave grátis: abra o site, copie a chave e cole abaixo - uma basta.", pt = "As capas da biblioteca são caixas do RetroAchievements, ou ícones do SteamGridDB para os jogos que ele não tem. Cada um precisa da sua própria chave gratuita: abra o site, copie a chave e cole-a abaixo - uma basta."),
    "Skip this if you like - you can add a key any time in SETTINGS > COVER ART." to Tr(ja = "スキップしても だいじょうぶ - キーは いつでも せってい > カバー で いれられます。", fr = "Passez si vous voulez - vous pourrez ajouter une clé à tout moment dans OPTIONS > JAQUETTES.", de = "Überspring das ruhig - einen Schlüssel kannst du jederzeit unter OPTIONEN > COVER eingeben.", it = "Saltalo se vuoi - puoi aggiungere una chiave quando vuoi in OPZIONI > COPERTINE.", es = "Omítelo si quieres - puedes añadir una clave cuando quieras en AJUSTES > PORTADAS.", br = "Pule isto se quiser - você pode adicionar uma chave quando quiser em CONFIGURAÇÕES > CAPAS.", pt = "Salte isto se quiser - pode adicionar uma chave quando quiser em DEFINIÇÕES > CAPAS."),
    "OPEN {0}" to Tr(ja = "{0}を ひらく", fr = "OUVRIR {0}", de = "{0} ÖFFNEN", it = "APRI {0}", es = "ABRIR {0}", br = "ABRIR {0}", pt = "ABRIR {0}"),
    "GET KEY" to Tr(ja = "キーを とる", fr = "OBTENIR LA CLÉ", de = "SCHLÜSSEL HOLEN", it = "OTTIENI CHIAVE", es = "OBTENER CLAVE", br = "OBTER CHAVE", pt = "OBTER CHAVE"),
    "SD CARD" to Tr(ja = "SDカード", fr = "CARTE SD", de = "SD-KARTE", it = "SCHEDA SD", es = "TARJETA SD", br = "CARTÃO SD", pt = "CARTÃO SD"),
    // In-game HUD (EmulatorEngine / PokeDaisyActivity).
    "Game restarted" to Tr(ja = "ゲームを リスタートしました", fr = "Jeu redémarré", de = "Spiel neu gestartet", it = "Gioco riavviato", es = "Juego reiniciado", br = "Jogo reiniciado", pt = "Jogo reiniciado"),
    "Fast-forward" to Tr(ja = "はやおくり", fr = "Avance rapide", de = "Vorspulen", it = "Avanti veloce", es = "Avance rápido", br = "Avanço rápido", pt = "Avanço rápido"),
    // EXPAND's one-time introduction (ExpandIntro).
    "WHAT'S NEW" to Tr(ja = "あたらしい こと", fr = "NOUVEAUTÉS", de = "NEUIGKEITEN", it = "NOVITÀ", es = "NOVEDADES", br = "NOVIDADES", pt = "NOVIDADES"),
    "FIXES" to Tr(ja = "なおした こと", fr = "CORRECTIFS", de = "BEHOBEN", it = "CORREZIONI", es = "ARREGLOS", br = "CORREÇÕES", pt = "CORREÇÕES"),
    "NEW: EXPAND" to Tr(ja = "NEW: ひろげる", fr = "NOUVEAU : ÉTENDRE", de = "NEU: ERWEITERN", it = "NOVITÀ: ESPANDI", es = "NUEVO: AMPLIAR", br = "NOVO: EXPANDIR", pt = "NOVO: EXPANDIR"),
    "See more of the world around you. EXPAND draws the map past the game's edges, so the whole screen is the game: no black bars, nothing stretched." to Tr(ja = "まわりの せかいが もっと みえる。 ひろげるは ゲームの はしの さきまで マップを えがくので がめん ぜんぶが ゲームに なります。 くろい おびも ひきのばしも なし。", fr = "Voyez plus du monde autour de vous. ÉTENDRE dessine la carte au-delà des bords du jeu : tout l'écran est le jeu, sans bandes noires ni étirement.", de = "Sieh mehr von der Welt um dich herum. ERWEITERN zeichnet die Karte über die Ränder des Spiels hinaus: Der ganze Bildschirm ist das Spiel, ohne schwarze Balken, nichts verzerrt.", it = "Vedi di più del mondo intorno a te. ESPANDI disegna la mappa oltre i bordi del gioco: tutto lo schermo è il gioco, senza bande nere né stiramenti.", es = "Ve más del mundo a tu alrededor. AMPLIAR dibuja el mapa más allá de los bordes del juego: toda la pantalla es el juego, sin franjas negras ni nada estirado.", br = "Veja mais do mundo ao seu redor. EXPANDIR desenha o mapa além das bordas do jogo, então a tela inteira é o jogo: sem barras pretas, nada esticado.", pt = "Veja mais do mundo à sua volta. EXPANDIR desenha o mapa além das margens do jogo, por isso o ecrã inteiro é o jogo: sem barras pretas, nada esticado."),
    "Press R3 to zoom out and see further, and look around with the right stick. Battles, menus and conversations zoom back in by themselves." to Tr(ja = "R3で ズームアウトして とおくまで みえる。 みぎスティックで みまわせます。 バトルや メニューや かいわでは じどうで もどります。", fr = "R3 pour dézoomer et voir plus loin, le stick droit pour regarder autour. Combats, menus et dialogues rezooment d'eux-mêmes.", de = "R3 zoomt heraus, damit du weiter siehst, mit dem rechten Stick schaust du dich um. Kämpfe, Menüs und Gespräche zoomen von selbst wieder heran.", it = "Premi R3 per allontanare la vista e vedere più lontano, guardati intorno con lo stick destro. Lotte, menu e dialoghi tornano vicini da soli.", es = "Pulsa R3 para alejar la vista y ver más lejos, y mira alrededor con el stick derecho. Combates, menús y conversaciones vuelven a acercarse solos.", br = "Aperte R3 para afastar a câmera e ver mais longe, e olhe em volta com o analógico direito. Batalhas, menus e conversas voltam a aproximar sozinhos.", pt = "Carregue em R3 para afastar a câmara e ver mais longe, e olhe em volta com o analógico direito. Batalhas, menus e conversas voltam a aproximar sozinhos."),
    "Works in selected games, with more added all the time. Change it any time in SETTINGS > ASPECT." to Tr(ja = "いくつかの ゲームで つかえます。 たいおうゲームは どんどん ふえます。 せってい > アスペクトで いつでも かえられます。", fr = "Fonctionne dans certains jeux, et d'autres arrivent sans cesse. À changer quand vous voulez dans OPTIONS > FORMAT.", de = "Funktioniert in ausgewählten Spielen, und es kommen ständig neue dazu. Jederzeit änderbar unter OPTIONEN > FORMAT.", it = "Funziona in alcuni giochi, e se ne aggiungono sempre di nuovi. Puoi cambiarlo quando vuoi in OPZIONI > FORMATO.", es = "Funciona en algunos juegos, y añadimos más todo el tiempo. Cámbialo cuando quieras en AJUSTES > FORMATO.", br = "Funciona em alguns jogos, e sempre adicionamos mais. Mude quando quiser em CONFIGURAÇÕES > PROPORÇÃO.", pt = "Funciona em alguns jogos, e estamos sempre a adicionar mais. Mude quando quiser em DEFINIÇÕES > PROPORÇÃO."),
    "Change it any time in SETTINGS > ASPECT." to Tr(ja = "せってい > アスペクトで いつでも かえられます。", fr = "À changer quand vous voulez dans OPTIONS > FORMAT.", de = "Jederzeit änderbar unter OPTIONEN > FORMAT.", it = "Puoi cambiarlo quando vuoi in OPZIONI > FORMATO.", es = "Cámbialo cuando quieras en AJUSTES > FORMATO.", br = "Mude quando quiser em CONFIGURAÇÕES > PROPORÇÃO.", pt = "Mude quando quiser em DEFINIÇÕES > PROPORÇÃO."),
    "EXPAND WORKS IN THIS GAME" to Tr(ja = "この ゲームは ひろげるに たいおう", fr = "ÉTENDRE MARCHE DANS CE JEU", de = "ERWEITERN GEHT IN DIESEM SPIEL", it = "ESPANDI FUNZIONA IN QUESTO GIOCO", es = "AMPLIAR FUNCIONA EN ESTE JUEGO", br = "EXPANDIR FUNCIONA NESTE JOGO", pt = "EXPANDIR FUNCIONA NESTE JOGO"),
    "NOT NOW" to Tr(ja = "あとで", fr = "PLUS TARD", de = "SPÄTER", it = "NON ORA", es = "AHORA NO", br = "AGORA NÃO", pt = "AGORA NÃO"),
    "TURN ON" to Tr(ja = "オンにする", fr = "ACTIVER", de = "EINSCHALTEN", it = "ATTIVA", es = "ACTIVAR", br = "ATIVAR", pt = "ATIVAR"),
    "EXPAND hit a problem and is off for this game" to Tr(ja = "ひろげるで もんだいが おきたので この ゲームでは オフに しました", fr = "ÉTENDRE a eu un problème : désactivé pour ce jeu", de = "ERWEITERN hatte ein Problem und ist für dieses Spiel aus", it = "ESPANDI ha avuto un problema: disattivato per questo gioco", es = "AMPLIAR tuvo un problema y se desactivó para este juego", br = "EXPANDIR teve um problema e foi desativado neste jogo", pt = "EXPANDIR teve um problema e foi desativado neste jogo"),
    "Zoom {0}" to Tr(ja = "ズーム {0}", fr = "Zoom {0}", de = "Zoom {0}", it = "Zoom {0}", es = "Zoom {0}", br = "Zoom {0}", pt = "Zoom {0}"),
    "Zoom needs ASPECT > EXPAND" to Tr(ja = "ズームは アスペクト > ひろげる で", fr = "Le zoom demande FORMAT > ÉTENDRE", de = "Zoom braucht FORMAT > ERWEITERN", it = "Lo zoom richiede FORMATO > ESPANDI", es = "El zoom necesita FORMATO > AMPLIAR", br = "O zoom precisa de PROPORÇÃO > EXPANDIR", pt = "O zoom precisa de PROPORÇÃO > EXPANDIR"),
    "Soft reset" to Tr(ja = "ソフトリセット", fr = "Réinitialisation douce", de = "Soft-Reset", it = "Reset soft", es = "Reinicio suave", br = "Reinício suave", pt = "Reinício suave"),
    "Rewinding" to Tr(ja = "まきもどし ちゅう", fr = "Retour arrière", de = "Zurückspulen", it = "Riavvolgimento", es = "Rebobinando", br = "Rebobinando", pt = "A rebobinar"),
    "Rewind is off - turn it on in SETTINGS" to Tr(ja = "まきもどしは オフです - せっていで オンに", fr = "Retour arrière désactivé - activez-le dans OPTIONS", de = "Zurückspulen ist aus - in OPTIONEN einschalten", it = "Riavvolgimento disattivato - attivalo in OPZIONI", es = "Rebobinar está desactivado - actívalo en AJUSTES", br = "Rebobinar está desativado - ative em CONFIG.", pt = "Rebobinar está desativado - ative-o em DEFINIÇÕES"),
