    "DEVELOPER" to Tr(ja = "かいはつ", fr = "DÉVELOPPEUR", de = "ENTWICKLER", it = "SVILUPPATORE", es = "DESARROLLADOR", br = "DESENVOLVEDOR", pt = "PROGRAMADOR"),
    "PUBLISHER" to Tr(ja = "はんばい", fr = "ÉDITEUR", de = "PUBLISHER", it = "EDITORE", es = "EDITOR", br = "DISTRIBUIDORA", pt = "EDITORA"),
    "GENRE" to Tr(ja = "ジャンル", fr = "GENRE", de = "GENRE", it = "GENERE", es = "GÉNERO", br = "GÊNERO", pt = "GÉNERO"),
