    "RATING" to Tr(ja = "ひょうか", fr = "NOTE", de = "WERTUNG", it = "VOTO", es = "NOTA", br = "NOTA", pt = "NOTA"),
    "Sign in to ScreenScraper in SETTINGS for this game's box art, screenshots, video and story." to Tr(ja = "せってい で ScreenScraperに ログインすると この ゲームの パッケージ、 スクリーンショット、 どうが、 あらすじが でます。", fr = "Connectez-vous à ScreenScraper dans OPTIONS pour la jaquette, les captures, la vidéo et le résumé de ce jeu.", de = "Melde dich in OPTIONEN bei ScreenScraper an für Cover, Screenshots, Video und Story dieses Spiels.", it = "Accedi a ScreenScraper in OPZIONI per copertina, screenshot, video e trama di questo gioco.", es = "Inicia sesión en ScreenScraper en AJUSTES para la portada, capturas, vídeo e historia de este juego.", br = "Entre no ScreenScraper em CONFIG. para ver a capa, capturas, vídeo e história deste jogo.", pt = "Inicie sessão no ScreenScraper em DEFINIÇÕES para ver a capa, capturas, vídeo e história deste jogo."),
    "ScreenScraper has nothing for this game yet." to Tr(ja = "ScreenScraperには この ゲームの ものが まだ ありません。", fr = "ScreenScraper n'a encore rien pour ce jeu.", de = "ScreenScraper hat für dieses Spiel noch nichts.", it = "ScreenScraper non ha ancora nulla per questo gioco.", es = "ScreenScraper aún no tiene nada de este juego.", br = "O ScreenScraper ainda não tem nada deste jogo.", pt = "O ScreenScraper ainda não tem nada deste jogo."),
