    "Hide password" to Tr(ja = "パスワードを かくす", fr = "Masquer le mot de passe", de = "Passwort verbergen", it = "Nascondi password", es = "Ocultar contraseña", br = "Ocultar senha", pt = "Ocultar palavra-passe"),
    "ScreenScraper says: {0}" to Tr(ja = "ScreenScraperの こたえ: {0}", fr = "ScreenScraper répond : {0}", de = "ScreenScraper sagt: {0}", it = "ScreenScraper risponde: {0}", es = "ScreenScraper dice: {0}", br = "O ScreenScraper diz: {0}", pt = "O ScreenScraper diz: {0}"),
    "ScreenScraper sent an answer the app can't read" to Tr(ja = "ScreenScraperの こたえが よめません", fr = "ScreenScraper a envoyé une réponse illisible", de = "ScreenScraper schickte eine unlesbare Antwort", it = "ScreenScraper ha inviato una risposta illeggibile", es = "ScreenScraper envió una respuesta ilegible", br = "O ScreenScraper enviou uma resposta que o app não consegue ler", pt = "O ScreenScraper enviou uma resposta que a app não consegue ler"),
    "This build has no ScreenScraper developer login, so ScreenScraper may refuse to sign in. Release builds have one." to Tr(ja = "この ビルドには ScreenScraperの かいはつしゃ ログインが ないので ログインを ことわられることが あります。 リリース ビルドには あります。", fr = "Cette version n'a pas d'identifiant développeur ScreenScraper : la connexion peut être refusée. Les versions publiées en ont un.", de = "Diese Version hat keinen ScreenScraper-Entwicklerzugang, die Anmeldung kann abgelehnt werden. Veröffentlichte Versionen haben einen.", it = "Questa versione non ha l'accesso sviluppatore ScreenScraper, quindi l'accesso può essere rifiutato. Le versioni pubblicate ce l'hanno.", es = "Esta versión no tiene acceso de desarrollador a ScreenScraper, así que puede rechazar el inicio de sesión. Las versiones publicadas lo tienen.", br = "Esta versão não tem login de desenvolvedor do ScreenScraper, então ele pode recusar a entrada. As versões publicadas têm.", pt = "Esta versão não tem credenciais de programador do ScreenScraper, por isso pode recusar o início de sessão. As versões publicadas têm."),
    // PC BOXES (a game's save, read and rearranged from the library)
    "PC BOXES" to Tr(ja = "パソコンの ボックス", fr = "BOÎTES PC", de = "PC-BOXEN", it = "BOX PC", es = "CAJAS PC", br = "CAIXAS DO PC", pt = "CAIXAS DO PC"),
    "PC BOXES reads FireRed, LeafGreen, Emerald, Ruby and Sapphire saves (and builds that keep their save layout). This game's isn't one yet." to Tr(ja = "パソコンの ボックスは ファイアレッド・リーフグリーン・エメラルド・ルビー・サファイアの セーブ (と おなじ かたちの セーブ)を よみます。 この ゲームの セーブには まだ たいおう していません。", fr = "BOÎTES PC lit les sauvegardes de Rouge Feu, Vert Feuille, Émeraude, Rubis et Saphir (et des versions au même format). Pas encore celle de ce jeu.", de = "PC-BOXEN liest Spielstände von Feuerrot, Blattgrün, Smaragd, Rubin und Saphir (und Versionen mit demselben Format). Den dieses Spiels noch nicht.", it = "BOX PC legge i salvataggi di Rosso Fuoco, Verde Foglia, Smeraldo, Rubino e Zaffiro (e versioni con lo stesso formato). Non ancora quello di questo gioco.", es = "CAJAS PC lee partidas de Rojo Fuego, Verde Hoja, Esmeralda, Rubí y Zafiro (y versiones con el mismo formato). Aún no la de este juego.", br = "CAIXAS DO PC lê saves de FireRed, LeafGreen, Emerald, Ruby e Sapphire (e versões com o mesmo formato de save). O deste jogo ainda não.", pt = "CAIXAS DO PC lê gravações de FireRed, LeafGreen, Emerald, Ruby e Sapphire (e versões com o mesmo formato). A deste jogo ainda não."),
    "No save yet - save once in the game first." to Tr(ja = "セーブが まだ ありません。 さきに ゲームで いちど セーブしてください。", fr = "Pas encore de sauvegarde : sauvegardez d'abord une fois dans le jeu.", de = "Noch kein Spielstand - speichere zuerst einmal im Spiel.", it = "Nessun salvataggio: salva prima una volta nel gioco.", es = "Aún no hay partida: guarda una vez en el juego primero.", br = "Ainda não há save - salve uma vez no jogo primeiro.", pt = "Ainda não há gravação - guarde uma vez no jogo primeiro."),
    "Can't read the save {0}" to Tr(ja = "セーブ {0} を よめません", fr = "Impossible de lire la sauvegarde {0}", de = "Spielstand {0} kann nicht gelesen werden", it = "Impossibile leggere il salvataggio {0}", es = "No se puede leer la partida {0}", br = "Não é possível ler o save {0}", pt = "Não é possível ler a gravação {0}"),
    "This save doesn't look like a {0} save ({1}), so it's left alone." to Tr(ja = "この セーブは {0}の セーブに みえません ({1})。 そのままに します。", fr = "Cette sauvegarde ne ressemble pas à une sauvegarde {0} ({1}) : elle n'est pas touchée.", de = "Dieser Spielstand sieht nicht nach {0} aus ({1}), er bleibt unberührt.", it = "Questo salvataggio non sembra di {0} ({1}): resta com'è.", es = "Esta partida no parece de {0} ({1}): no se toca.", br = "Este save não parece de {0} ({1}), então não será alterado.", pt = "Esta gravação não parece de {0} ({1}), por isso não é alterada."),
    "Saved. The previous save is in {0}" to Tr(ja = "セーブしました。 まえの セーブは {0} に あります", fr = "Sauvegardé. L'ancienne sauvegarde est dans {0}", de = "Gespeichert. Der vorige Spielstand liegt in {0}", it = "Salvato. Il salvataggio precedente è in {0}", es = "Guardado. La partida anterior está en {0}", br = "Salvo. O save anterior está em {0}", pt = "Guardado. A gravação anterior está em {0}"),
    "Reading the save…" to Tr(ja = "セーブを よんでいます…", fr = "Lecture de la sauvegarde…", de = "Spielstand wird gelesen…", it = "Lettura del salvataggio…", es = "Leyendo la partida…", br = "Lendo o save…", pt = "A ler a gravação…"),
    "The save changed since it was opened - open it again" to Tr(ja = "ひらいてから セーブが かわりました。 もういちど ひらいてください", fr = "La sauvegarde a changé depuis son ouverture : rouvrez-la", de = "Der Spielstand hat sich seit dem Öffnen geändert - öffne ihn erneut", it = "Il salvataggio è cambiato dopo l'apertura: riaprilo", es = "La partida cambió desde que se abrió: ábrela de nuevo", br = "O save mudou desde que foi aberto - abra de novo", pt = "A gravação mudou desde que foi aberta - abra-a de novo"),
    "Can't back up the save in {0} - nothing was changed" to Tr(ja = "{0} に セーブの バックアップを つくれません。 なにも かえていません", fr = "Impossible de copier la sauvegarde dans {0} : rien n'a été modifié", de = "Kein Backup in {0} möglich - nichts wurde geändert", it = "Impossibile fare il backup in {0}: nulla è stato cambiato", es = "No se puede copiar la partida en {0}: no se cambió nada", br = "Não é possível fazer backup do save em {0} - nada foi alterado", pt = "Não é possível fazer cópia de segurança da gravação em {0} - nada foi alterado"),
    "The save didn't read back as written - the backup was put back" to Tr(ja = "かきこんだ セーブが ただしく よめません。 バックアップを もどしました", fr = "La sauvegarde ne se relit pas comme écrite : la copie a été remise", de = "Der Spielstand ließ sich nicht wie geschrieben lesen - das Backup wurde zurückgelegt", it = "Il salvataggio non si rilegge come scritto: il backup è stato rimesso", es = "La partida no se lee como se escribió: se repuso la copia", br = "O save não foi lido como foi gravado - o backup foi restaurado", pt = "A gravação não foi lida como foi escrita - a cópia de segurança foi reposta"),
    "Too small for a Gen 3 save ({0} bytes)" to Tr(ja = "だい3せだいの セーブには ちいさすぎます ({0} バイト)", fr = "Trop petit pour une sauvegarde de 3e génération ({0} octets)", de = "Zu klein für einen Spielstand der 3. Generation ({0} Bytes)", it = "Troppo piccolo per un salvataggio di 3ª generazione ({0} byte)", es = "Demasiado pequeño para una partida de 3.ª generación ({0} bytes)", br = "Pequeno demais para um save da Geração 3 ({0} bytes)", pt = "Pequeno demais para uma gravação da Geração 3 ({0} bytes)"),
    "The save is empty - save once in the game first" to Tr(ja = "セーブが からです。 さきに ゲームで いちど セーブしてください", fr = "La sauvegarde est vide : sauvegardez d'abord une fois dans le jeu", de = "Der Spielstand ist leer - speichere zuerst einmal im Spiel", it = "Il salvataggio è vuoto: salva prima una volta nel gioco", es = "La partida está vacía: guarda una vez en el juego primero", br = "O save está vazio - salve uma vez no jogo primeiro", pt = "A gravação está vazia - guarde uma vez no jogo primeiro"),
    "Neither save slot is intact - the game would call this save corrupted" to Tr(ja = "どちらの セーブも こわれています。 ゲームでも よめない セーブです", fr = "Aucun des deux emplacements n'est intact : le jeu la dirait corrompue", de = "Keiner der beiden Speicherplätze ist intakt - das Spiel hielte ihn für beschädigt", it = "Nessuno dei due slot è integro: il gioco lo direbbe danneggiato", es = "Ninguna de las dos ranuras está intacta: el juego la daría por dañada", br = "Nenhum dos dois espaços de save está intacto - o jogo diria que este save está corrompido", pt = "Nenhum dos dois espaços está intacto - o jogo diria que esta gravação está corrompida"),
    "The save's sectors disagree on its save counter" to Tr(ja = "セーブの セクターの カウンターが あいません", fr = "Les secteurs de la sauvegarde n'ont pas le même compteur", de = "Die Sektoren des Spielstands haben verschiedene Zähler", it = "I settori del salvataggio non hanno lo stesso contatore", es = "Los sectores de la partida no tienen el mismo contador", br = "Os setores do save não concordam no contador de saves", pt = "Os setores da gravação não concordam no contador"),
    "Tap where it goes - any box" to Tr(ja = "おく ばしょを タッチ (どの ボックスでも)", fr = "Touchez où le mettre (n'importe quelle boîte)", de = "Tippe, wohin es soll (jede Box)", it = "Tocca dove metterlo (qualsiasi box)", es = "Toca dónde ponerlo (cualquier caja)", br = "Toque onde colocar - qualquer caixa", pt = "Toque onde colocar - qualquer caixa"),
    "Not saved yet" to Tr(ja = "まだ セーブしていません", fr = "Pas encore sauvegardé", de = "Noch nicht gespeichert", it = "Non ancora salvato", es = "Aún sin guardar", br = "Ainda não salvo", pt = "Ainda não guardado"),
    "UNDO ALL" to Tr(ja = "ぜんぶ もどす", fr = "TOUT ANNULER", de = "ALLES ZURÜCK", it = "ANNULLA TUTTO", es = "DESHACER TODO", br = "DESFAZER TUDO", pt = "DESFAZER TUDO"),
    "SAVE CHANGES?" to Tr(ja = "セーブ しますか?", fr = "SAUVER LES CHANGEMENTS ?", de = "ÄNDERUNGEN SICHERN?", it = "SALVARE LE MODIFICHE?", es = "¿GUARDAR LOS CAMBIOS?", br = "SALVAR AS MUDANÇAS?", pt = "GUARDAR AS ALTERAÇÕES?"),
    "Written the way the game saves: the save as it is now stays in the file as the game's fallback, and a copy goes to pokedaisy-backups. The game starts from the save next time, not from a resume state." to Tr(ja = "ゲームと おなじ やりかたで かきこみます: いまの セーブは ファイルの なかに ゲームの よびとして のこり、 コピーが pokedaisy-backups に はいります。 つぎは つづきの ステートでなく セーブから はじまります。", fr = "Écrit comme le jeu sauvegarde : la sauvegarde actuelle reste dans le fichier comme secours du jeu, et une copie va dans pokedaisy-backups. Le jeu repartira de la sauvegarde, pas d'un état de reprise.", de = "So geschrieben, wie das Spiel speichert: Der jetzige Spielstand bleibt als Rückfall des Spiels in der Datei, eine Kopie kommt nach pokedaisy-backups. Das Spiel startet nächstes Mal vom Spielstand, nicht von einem Fortsetzungsstand.", it = "Scritto come salva il gioco: il salvataggio attuale resta nel file come riserva del gioco e una copia va in pokedaisy-backups. Il gioco ripartirà dal salvataggio, non da uno stato di ripresa.", es = "Se escribe como guarda el juego: la partida actual queda en el archivo como respaldo del juego y una copia va a pokedaisy-backups. El juego empezará desde la partida, no desde un estado de reanudación.", br = "Gravado do jeito que o jogo salva: o save atual fica no arquivo como reserva do jogo, e uma cópia vai para pokedaisy-backups. Na próxima vez o jogo começa do save, não de um estado de retomada.", pt = "Escrito como o jogo guarda: a gravação atual fica no ficheiro como reserva do jogo, e uma cópia vai para pokedaisy-backups. Da próxima vez, o jogo começa da gravação, não de um estado de retoma."),
    "DISCARD CHANGES?" to Tr(ja = "かえた ことを すてますか?", fr = "ABANDONNER LES CHANGEMENTS ?", de = "ÄNDERUNGEN VERWERFEN?", it = "SCARTARE LE MODIFICHE?", es = "¿DESCARTAR LOS CAMBIOS?", br = "DESCARTAR AS MUDANÇAS?", pt = "DESCARTAR AS ALTERAÇÕES?"),
    "Your changes aren't saved. Leave without saving them?" to Tr(ja = "かえた ことは セーブ していません。 セーブせずに もどりますか?", fr = "Les changements ne sont pas sauvegardés. Quitter sans les sauver ?", de = "Die Änderungen sind nicht gespeichert. Ohne Speichern verlassen?", it = "Le modifiche non sono salvate. Uscire senza salvarle?", es = "Los cambios no están guardados. ¿Salir sin guardarlos?", br = "Suas mudanças não foram salvas. Sair sem salvar?", pt = "As alterações não foram guardadas. Sair sem guardar?"),
    "DISCARD" to Tr(ja = "すてる", fr = "ABANDONNER", de = "VERWERFEN", it = "SCARTA", es = "DESCARTAR", br = "DESCARTAR", pt = "DESCARTAR"),
    "ID No." to Tr(ja = "IDNo.", fr = "N° ID", de = "ID-Nr.", it = "N. ID", es = "N.º ID", br = "N. ID", pt = "N. ID"),
    "Previous box" to Tr(ja = "まえの ボックス", fr = "Boîte précédente", de = "Vorige Box", it = "Box precedente", es = "Caja anterior", br = "Caixa anterior", pt = "Caixa anterior"),
    "Next box" to Tr(ja = "つぎの ボックス", fr = "Boîte suivante", de = "Nächste Box", it = "Box successivo", es = "Caja siguiente", br = "Próxima caixa", pt = "Caixa seguinte"),
    "Tap a Pokémon to see it, then MOVE to put it in another slot." to Tr(ja = "ポケモンを タッチすると みられます。 うつす で べつの ばしょに おけます。", fr = "Touchez un Pokémon pour le voir, puis DÉPLACER pour le mettre ailleurs.", de = "Tippe auf ein Pokémon, um es zu sehen, dann VERSCHIEBEN für einen anderen Platz.", it = "Tocca un Pokémon per vederlo, poi SPOSTA per metterlo altrove.", es = "Toca un Pokémon para verlo y luego MOVER para ponerlo en otro sitio.", br = "Toque em um Pokémon para vê-lo e depois em MOVER para colocá-lo em outro espaço.", pt = "Toque num Pokémon para o ver e depois em MOVER para o pôr noutro espaço."),
    "STATE" to Tr(ja = "じょうたい", fr = "ÉTAT", de = "ZUSTAND", it = "STATO", es = "ESTADO", br = "ESTADO", pt = "ESTADO"),
    "BAD EGG" to Tr(ja = "ダメタマゴ", fr = "MAUVAIS ŒUF", de = "SCHLECHTES EI", it = "UOVO GUASTO", es = "HUEVO MALO", br = "OVO RUIM", pt = "OVO MAU"),
    "EGG" to Tr(ja = "タマゴ", fr = "ŒUF", de = "EI", it = "UOVO", es = "HUEVO", br = "OVO", pt = "OVO"),
    "SPECIES" to Tr(ja = "しゅるい", fr = "ESPÈCE", de = "ART", it = "SPECIE", es = "ESPECIE", br = "ESPÉCIE", pt = "ESPÉCIE"),
    "LEVEL" to Tr(ja = "レベル", fr = "NIVEAU", de = "LEVEL", it = "LIVELLO", es = "NIVEL", br = "NÍVEL", pt = "NÍVEL"),
    "ITEM" to Tr(ja = "もちもの", fr = "OBJET", de = "ITEM", it = "STRUMENTO", es = "OBJETO", br = "ITEM", pt = "ITEM"),
    "OT" to Tr(ja = "おや", fr = "DO", de = "OT", it = "AO", es = "EO", br = "TO", pt = "TO"),
    // PC BOXES: editing (the BAG page, a Pokémon's item and moves)
    "BOXES" to Tr(ja = "ボックス", fr = "BOÎTES", de = "BOXEN", it = "BOX", es = "CAJAS", br = "CAIXAS", pt = "CAIXAS"),
    "MONEY" to Tr(ja = "おこづかい", fr = "ARGENT", de = "GELD", it = "SOLDI", es = "DINERO", br = "DINHEIRO", pt = "DINHEIRO"),
    "COINS" to Tr(ja = "コイン", fr = "JETONS", de = "MÜNZEN", it = "GETTONI", es = "FICHAS", br = "FICHAS", pt = "FICHAS"),
    "ADD ITEM" to Tr(ja = "どうぐを ふやす", fr = "AJOUTER UN OBJET", de = "ITEM HINZUFÜGEN", it = "AGGIUNGI STRUMENTO", es = "AÑADIR OBJETO", br = "ADICIONAR ITEM", pt = "ADICIONAR ITEM"),
    "ADD MOVE" to Tr(ja = "わざを ふやす", fr = "AJOUTER UNE CAPACITÉ", de = "ATTACKE HINZUFÜGEN", it = "AGGIUNGI MOSSA", es = "AÑADIR MOVIMIENTO", br = "ADICIONAR GOLPE", pt = "ADICIONAR GOLPE"),
    "MIN" to Tr(ja = "MIN", fr = "MIN", de = "MIN", it = "MIN", es = "MÍN", br = "MÍN", pt = "MÍN"),
    "Tap its item or a move to change it" to Tr(ja = "もちものか わざを タッチすると かえられます", fr = "Touchez son objet ou une capacité pour les changer", de = "Tippe auf Item oder Attacke, um sie zu ändern", it = "Tocca lo strumento o una mossa per cambiarli", es = "Toca su objeto o un movimiento para cambiarlo", br = "Toque no item ou em um golpe para mudá-lo", pt = "Toque no item ou num golpe para o mudar"),
    "Key items and HMs stay as the game gave them" to Tr(ja = "だいじな ものと ひでんマシンは ゲームが くれた ままです", fr = "Objets rares et CS restent tels que le jeu les a donnés", de = "Basis-Items und VM bleiben, wie das Spiel sie gab", it = "Strumenti base e MN restano come li ha dati il gioco", es = "Los objetos clave y las MO se quedan como los dio el juego", br = "Itens-chave e MOs ficam como o jogo os deu", pt = "Itens-chave e MOs ficam como o jogo os deu"),
    // TRADE (two saves' PC boxes)
    "No other game here has a save PC BOXES can read" to Tr(ja = "パソコンの ボックスで よめる セーブの ゲームが ほかに ありません", fr = "Aucun autre jeu ici n'a une sauvegarde lisible par BOÎTES PC", de = "Kein anderes Spiel hier hat einen Spielstand, den PC-BOXEN lesen kann", it = "Nessun altro gioco qui ha un salvataggio leggibile da BOX PC", es = "Ningún otro juego aquí tiene una partida que CAJAS PC pueda leer", br = "Nenhum outro jogo aqui tem um save que CAIXAS DO PC consiga ler", pt = "Nenhum outro jogo aqui tem uma gravação que CAIXAS DO PC consiga ler"),
    "TRADE WITH" to Tr(ja = "こうかんする あいて", fr = "ÉCHANGER AVEC", de = "TAUSCHEN MIT", it = "SCAMBIA CON", es = "INTERCAMBIAR CON", br = "TROCAR COM", pt = "TROCAR COM"),
    "Both games use the same save file" to Tr(ja = "ふたつの ゲームが おなじ セーブを つかっています", fr = "Les deux jeux utilisent la même sauvegarde", de = "Beide Spiele nutzen denselben Spielstand", it = "I due giochi usano lo stesso salvataggio", es = "Los dos juegos usan la misma partida", br = "Os dois jogos usam o mesmo arquivo de save", pt = "Os dois jogos usam o mesmo ficheiro de gravação"),
    "A Bad Egg can't be traded" to Tr(ja = "ダメタマゴは こうかん できません", fr = "Un Mauvais Œuf ne s'échange pas", de = "Ein schlechtes Ei kann nicht getauscht werden", it = "Un Uovo Guasto non si può scambiare", es = "Un Huevo Malo no se puede intercambiar", br = "Um Ovo Ruim não pode ser trocado", pt = "Um Ovo Mau não pode ser trocado"),
    "{0} has no National Dex yet, so no eggs" to Tr(ja = "{0}は まだ ぜんこくずかんが ないので タマゴは だめです", fr = "{0} n'a pas encore le Pokédex National : pas d'œufs", de = "{0} hat noch keinen Nationalen Pokédex: keine Eier", it = "{0} non ha ancora il Pokédex Nazionale: niente uova", es = "{0} aún no tiene la Pokédex Nacional: sin huevos", br = "{0} ainda não tem a Pokédex Nacional, então nada de ovos", pt = "{0} ainda não tem a Pokédex Nacional, por isso nada de ovos"),
    "{0} has no National Dex yet, so no {1}" to Tr(ja = "{0}は まだ ぜんこくずかんが ないので {1}は だめです", fr = "{0} n'a pas encore le Pokédex National : pas de {1}", de = "{0} hat noch keinen Nationalen Pokédex: kein {1}", it = "{0} non ha ancora il Pokédex Nazionale: niente {1}", es = "{0} aún no tiene la Pokédex Nacional: sin {1}", br = "{0} ainda não tem a Pokédex Nacional, então nada de {1}", pt = "{0} ainda não tem a Pokédex Nacional, por isso nada de {1}"),
    "This {0} isn't from an event, so the games won't trade it" to Tr(ja = "この {0}は イベントの ポケモンでは ないので こうかん できません", fr = "Ce {0} ne vient pas d'un événement : les jeux ne l'échangent pas", de = "Dieses {0} stammt nicht von einem Event: die Spiele tauschen es nicht", it = "Questo {0} non viene da un evento: i giochi non lo scambiano", es = "Este {0} no viene de un evento: los juegos no lo intercambian", br = "Este {0} não é de um evento, então os jogos não o trocam", pt = "Este {0} não é de um evento, por isso os jogos não o trocam"),
    "Mail and Enigma Berries stay with their save: take it off in the game first" to Tr(ja = "メールと ナゾのみは セーブに のこります。 さきに ゲームで はずしてください", fr = "Lettres et Baies Énigma restent avec leur sauvegarde : retirez-les d'abord dans le jeu", de = "Briefe und Enigmabeeren bleiben bei ihrem Spielstand: nimm sie zuerst im Spiel ab", it = "Lettere e Baccaenigma restano nel loro salvataggio: toglile prima nel gioco", es = "Las cartas y las Bayas Enigma se quedan en su partida: quítalas antes en el juego", br = "Cartas e Frutas Enigma ficam no seu save: tire-as no jogo primeiro", pt = "Cartas e Frutas Enigma ficam na sua gravação: retire-as primeiro no jogo"),
    "{0} links with Ruby, Sapphire and Emerald only after the Sevii Islands" to Tr(ja = "{0}は ナナシマの あとでないと ルビー・サファイア・エメラルドと つなげません", fr = "{0} ne se connecte à Rubis, Saphir et Émeraude qu'après les Îles Sevii", de = "{0} verbindet sich erst nach den Sevii Eilanden mit Rubin, Saphir und Smaragd", it = "{0} si collega a Rubino, Zaffiro e Smeraldo solo dopo le Isole Settipelago", es = "{0} solo conecta con Rubí, Zafiro y Esmeralda tras las Islas Sete", br = "{0} só se conecta com Ruby, Sapphire e Emerald depois das Ilhas Sevii", pt = "{0} só se liga a Ruby, Sapphire e Emerald depois das Ilhas Sevii"),
    "There's no Pokémon there" to Tr(ja = "そこに ポケモンは いません", fr = "Il n'y a pas de Pokémon ici", de = "Dort ist kein Pokémon", it = "Lì non c'è nessun Pokémon", es = "Ahí no hay ningún Pokémon", br = "Não há nenhum Pokémon aí", pt = "Não há nenhum Pokémon aí"),
    "That slot isn't empty" to Tr(ja = "その ばしょは あいていません", fr = "Cet emplacement n'est pas vide", de = "Dieser Platz ist nicht frei", it = "Quel posto non è vuoto", es = "Ese hueco no está vacío", br = "Esse espaço não está vazio", pt = "Esse espaço não está vazio"),
    "{0} goes to {1}" to Tr(ja = "{0}が {1}へ いきます", fr = "{0} part vers {1}", de = "{0} geht nach {1}", it = "{0} va in {1}", es = "{0} va a {1}", br = "{0} vai para {1}", pt = "{0} vai para {1}"),
    "{0} for {1}" to Tr(ja = "{0}と {1}を こうかん", fr = "{0} contre {1}", de = "{0} gegen {1}", it = "{0} per {1}", es = "{0} por {1}", br = "{0} por {1}", pt = "{0} por {1}"),
    "Pick a slot on each side: a Pokémon for a Pokémon, or one for an empty slot" to Tr(ja = "りょうほうで ばしょを えらんでください: ポケモンと ポケモン、 または ポケモンと あいている ばしょ", fr = "Choisissez un emplacement de chaque côté : un Pokémon contre un Pokémon, ou vers un emplacement vide", de = "Wähle auf jeder Seite einen Platz: Pokémon gegen Pokémon, oder eines auf einen freien Platz", it = "Scegli un posto per lato: un Pokémon per un Pokémon, o uno verso un posto vuoto", es = "Elige un hueco en cada lado: un Pokémon por otro, o uno a un hueco vacío", br = "Escolha um espaço de cada lado: um Pokémon por outro, ou um para um espaço vazio", pt = "Escolha um espaço de cada lado: um Pokémon por outro, ou um para um espaço vazio"),
    "SEND" to Tr(ja = "おくる", fr = "ENVOYER", de = "SENDEN", it = "INVIA", es = "ENVIAR", br = "ENVIAR", pt = "ENVIAR"),
    "SAVE BOTH?" to Tr(ja = "りょうほう セーブ しますか?", fr = "SAUVER LES DEUX ?", de = "BEIDE SICHERN?", it = "SALVARE ENTRAMBI?", es = "¿GUARDAR AMBAS?", br = "SALVAR OS DOIS?", pt = "GUARDAR AS DUAS?"),
    "Both saves are written the way the game saves, each backed up to pokedaisy-backups first. If the second can't be written, the first is put back, so no Pokémon is lost or copied." to Tr(ja = "ふたつの セーブを ゲームと おなじ やりかたで かきこみます。 さきに それぞれを pokedaisy-backups に コピーします。 ふたつめが かけなければ ひとつめを もどすので、 ポケモンが きえたり ふえたり しません。", fr = "Les deux sauvegardes sont écrites comme le jeu sauvegarde, chacune copiée d'abord dans pokedaisy-backups. Si la seconde échoue, la première est remise : aucun Pokémon n'est perdu ni copié.", de = "Beide Spielstände werden geschrieben, wie das Spiel speichert, jeder zuerst nach pokedaisy-backups kopiert. Klappt der zweite nicht, kommt der erste zurück: kein Pokémon geht verloren oder wird verdoppelt.", it = "Entrambi i salvataggi sono scritti come salva il gioco, ognuno copiato prima in pokedaisy-backups. Se il secondo non si scrive, il primo viene rimesso: nessun Pokémon perso o copiato.", es = "Las dos partidas se escriben como guarda el juego, cada una copiada antes en pokedaisy-backups. Si la segunda falla, la primera se repone: ningún Pokémon se pierde ni se duplica.", br = "Os dois saves são gravados do jeito que o jogo salva, cada um com backup em pokedaisy-backups antes. Se o segundo não puder ser gravado, o primeiro é restaurado, então nenhum Pokémon se perde ou é copiado.", pt = "As duas gravações são escritas como o jogo guarda, cada uma com cópia de segurança em pokedaisy-backups antes. Se a segunda não puder ser escrita, a primeira é reposta, por isso nenhum Pokémon se perde nem é copiado."),
    "The trades you made aren't saved. Leave without saving them?" to Tr(ja = "こうかんは セーブ していません。 セーブせずに もどりますか?", fr = "Les échanges ne sont pas sauvegardés. Quitter sans les sauver ?", de = "Die Tausche sind nicht gespeichert. Ohne Speichern verlassen?", it = "Gli scambi non sono salvati. Uscire senza salvarli?", es = "Los intercambios no están guardados. ¿Salir sin guardarlos?", br = "As trocas que você fez não foram salvas. Sair sem salvar?", pt = "As trocas que fez não foram guardadas. Sair sem guardar?"),
    "EVOLVING!" to Tr(ja = "しんか!", fr = "ÉVOLUTION !", de = "ENTWICKLUNG!", it = "EVOLUZIONE!", es = "¡EVOLUCIÓN!", br = "EVOLUINDO!", pt = "A EVOLUIR!"),
    "{0} evolves into {1} when it arrives." to Tr(ja = "{0}は とどくと {1}に しんかします。", fr = "{0} évolue en {1} à son arrivée.", de = "{0} entwickelt sich bei Ankunft zu {1}.", it = "{0} si evolve in {1} all'arrivo.", es = "{0} evoluciona a {1} al llegar.", br = "{0} evolui para {1} ao chegar.", pt = "{0} evolui para {1} ao chegar."),
    "DON'T EVOLVE" to Tr(ja = "しんか させない", fr = "PAS D'ÉVOLUTION", de = "NICHT ENTWICKELN", it = "NON EVOLVERE", es = "NO EVOLUCIONAR", br = "NÃO EVOLUIR", pt = "NÃO EVOLUIR"),
)
